// Core domain types for the Office Daily Cash Ledger.
//
// Money is ALWAYS stored as an integer number of paisa. Never store or sum
// money as a float/rupee value anywhere in this file or in any DB table.
//
// IDs (Phase 10a): every entity's primary key and every foreign-key field
// that references one is a string UUID (crypto.randomUUID()), generated by
// the app before insert -- Dexie no longer assigns ids (no ++id anywhere).
// `id` is always present (never optional/undefined) since the app always
// generates it up front, unlike the old auto-increment scheme where Dexie
// left it undefined until insert. LedgerDay is the one exception: it's
// still keyed by `date` (a string), untouched by this migration.
//
// updatedAt (Phase 10b): every entity table below (all 8 tables Cloud Sync
// covers) carries an `updatedAt: number` (epoch ms), stamped by its
// add/edit/setActive function on every write. Transaction already had this
// since Phase 1; Phase 10b adds it to the other 7 tables specifically so
// sync can (a) find "changed since lastSyncedAt" rows to push and (b)
// resolve push/pull conflicts by last-write-wins. LedgerDays is NOT synced
// and has no updatedAt for this purpose -- see lib/sync.ts.

export type Direction = 'cash_in' | 'cash_out';

// Classifies what kind of cash movement a category/cash-in-type/transaction
// represents. Used by later phases' reporting (Staff, Savings/Finance,
// general Reports) to group movements without re-deriving the grouping
// from category names each time.
export type FlowClass =
  | 'operating_expense'
  | 'staff_payment'
  | 'savings_financial'
  | 'other_movement';

export interface Transaction {
  id: string;
  date: string; // 'YYYY-MM-DD'
  direction: Direction;
  amountPaisa: number; // integer, always >= 0
  categoryId: string | null; // set for cash_out, null for cash_in
  expenseHeadId: string | null; // optional, cash_out only
  cashInTypeId: string | null; // set for cash_in, null for cash_out
  description: string;
  staffId: string | null; // Salary/Advance (Phase 3-4) or general Cash Out (Phase 5)
  vehicleId: string | null; // general Cash Out only (Phase 5); never set by Salary/Advance
  institutionId: string | null; // Savings/Finance deposits & withdrawals only (Phase 6)
  referenceNumber: string | null;
  notes: string | null;
  flowClass: FlowClass;
  // Set on a Salary transaction when part of its gross amount recovers an
  // outstanding advance (Phase 4 Part D); null otherwise, including on
  // Advance-given transactions themselves (recovery isn't a cash movement).
  linkedAdvanceRecoveryPaisa: number | null;
  createdAt: number; // epoch ms
  updatedAt: number; // epoch ms
  deletedAt: number | null; // epoch ms, soft delete marker
}

export interface LedgerDay {
  date: string; // 'YYYY-MM-DD', primary key -- unaffected by the Phase 10a UUID migration
  openingBalancePaisa: number;
  cashInPaisa: number;
  cashOutPaisa: number;
  closingBalancePaisa: number;
  isManualOpening: boolean;
  recalculatedAt: number; // epoch ms
}

export interface Category {
  id: string;
  name: string;
  direction: Direction;
  flowClass: FlowClass;
  isCustom: boolean;
  active: boolean;
  updatedAt: number; // epoch ms (Phase 10b)
}

export interface ExpenseHead {
  id: string;
  categoryId: string;
  name: string;
  isCustom: boolean;
  active: boolean;
  updatedAt: number; // epoch ms (Phase 10b)
}

export interface CashInType {
  id: string;
  name: string;
  flowClass: FlowClass;
  isCustom: boolean;
  active: boolean;
  updatedAt: number; // epoch ms (Phase 10b)
}

// --- Phase 2+ tables (schema only, no seed data, no UI this phase) ---

export interface Staff {
  id: string;
  name: string;
  monthlySalaryPaisa: number;
  // Defaults to monthlySalaryPaisa when null (Phase 4 Part C).
  advanceLimitPaisa: number | null;
  joiningDate: string | null; // 'YYYY-MM-DD'
  active: boolean;
  // DEPRECATED (Phase 2): superseded by StaffVehicle join table; kept for
  // now, do not write to this field anymore, remove in a later cleanup
  // phase once StaffVehicle is proven in production. New code should read
  // StaffVehicle (see lib/staffVehicles.ts), not this field.
  assignedVehicleId: string | null; // Phase 5: optional default-suggestion link to Vehicle, set from the Staff form
  notes: string | null;
  // Phase 12g: other spellings/short forms the owner might type in Fast
  // Entry (e.g. a nickname) - matched alongside `name` by the staff-advance
  // pattern (fastEntrySuggestions.ts rule 4). Defaults to [] - purely
  // additive, never required.
  aliases: string[];
  // Phase 4: small practical staff-profile fields, added for the printable
  // ID card / summary view. Deliberately NOT an HR module — exactly these
  // four, nothing more. All default to null on migration and are optional
  // everywhere they're entered (see lib/staff.ts). Not matched by any Fast
  // Entry pattern rule — these are display/print fields only.
  employeeId: string | null;
  position: string | null;
  contactNumber: string | null;
  // A small base64 data: URL (from a client-side FileReader read of an
  // uploaded image), stored as a plain string field on the row — no
  // separate blob/file storage subsystem. Validated as an actual data: URL
  // by addStaff/editStaff when present (see lib/staff.ts).
  photoDataUrl: string | null;
  updatedAt: number; // epoch ms (Phase 10b)
}

export interface Vehicle {
  id: string;
  name: string;
  // Free text, e.g. "Motorbike" / "Van" / "Car" (Phase 5).
  vehicleType: string;
  registrationNumber: string | null;
  active: boolean;
  // NOTE (Phase 2): staff<->vehicle assignment now lives on the
  // StaffVehicle join table (see lib/staffVehicles.ts), not here and not
  // on Staff.assignedVehicleId (deprecated — see the note on that field
  // above). Still deliberately no mirrored assignedStaffId/vehicleIds
  // array on THIS type — the join table is the single source of truth in
  // both directions (getVehiclesForStaff / getStaffForVehicle), same
  // reasoning the original Phase 5 "no mirrored field" decision gave.
  // Phase 12g: other spellings/short forms (e.g. a nickname for the
  // vehicle). Not currently matched against by any Fast Entry pattern
  // (there's no vehicle-name pattern rule), but carried here for
  // consistency with Staff/FinancialInstitution and future use.
  aliases: string[];
  updatedAt: number; // epoch ms (Phase 10b)
}

// Phase 2: many-to-many staff<->vehicle relationship, superseding
// Staff.assignedVehicleId (see the DEPRECATED note on that field above).
// Same id-generation (crypto.randomUUID()) and updatedAt conventions as
// every other table.
//
// Phase 2 bugfix: this table IS synced (see SYNC_TABLES in lib/sync.ts),
// and this app's sync protocol is pure upsert-by-id with no tombstone/
// deletion mechanism — pushTable() only pushes rows that still exist
// locally, and pullTable() only inserts/overwrites, never deletes. A
// hard-deleted row is therefore invisible to sync (an unassignment on one
// device never propagates to another), so StaffVehicle rows are
// soft-deactivated instead, via `active: boolean` — the exact same
// convention every other master-data/relationship table here already
// uses (Staff, Vehicle, Category, ExpenseHead, CashInType,
// FinancialInstitution), not the `deletedAt` timestamp Transaction uses.
// See lib/staffVehicles.ts for the reactivate-on-reassign logic this
// requires.
export interface StaffVehicle {
  id: string;
  staffId: string;
  vehicleId: string;
  active: boolean;
  updatedAt: number; // epoch ms
}

export interface FinancialInstitution {
  id: string;
  name: string;
  active: boolean;
  // Phase 12g: other spellings/short forms the owner might type in Fast
  // Entry (e.g. a shortened branch name) - matched alongside `name` by the
  // institution-name pattern (fastEntrySuggestions.ts rule 3). Defaults to
  // [] - purely additive, never required.
  aliases: string[];
  updatedAt: number; // epoch ms (Phase 10b)
}

// Budgets are configuration, not a referenced master-data entity: no
// Transaction ever stores a budgetId, so a Budget row can be deleted
// outright when cleared (Phase 8 Part A's deliberate exception to the
// app's usual deactivate-only rule — see lib/budgets.ts clearBudget()).
export interface Budget {
  id: string;
  expenseHeadId: string;
  // Monthly limit only — advisory (Phase 8), never a hard block.
  monthlyLimitPaisa: number;
  updatedAt: number; // epoch ms (Phase 10b)
}

// --- Phase 10b: Cloud Sync ---

// Local-only config row (never synced to Firestore itself — it's what
// decides WHETHER syncing happens at all). Single row, fixed id.
export interface SyncConfig {
  id: 'singleton';
  syncCode: string;
  // Epoch ms of the last successful sync (push AND pull both completed).
  // null = never synced yet, so the next Sync Now treats every local row
  // as needing push and pulls every remote row.
  lastSyncedAt: number | null;
}
